import dates from "@/lib/article-dates.json";
import { laterDate } from "@/lib/publish";
import { allArticles } from "@/lib/site";

/**
 * When each guide was first published and last rewritten, from git history, and when each locale's
 * translation of it last changed.
 *
 * Generated by `npm run articles:dates` (run automatically before every build); see that script for
 * why the dates are read from commits rather than typed in. A guide with no entry yet (one added but
 * not committed) simply has no date, and the page omits it rather than showing a guess.
 *
 * A scheduled guide (publishAt) is committed before it goes live, so no date may precede its publish
 * day: published and modified, and each translation's date, are publishAt unless git is later.
 */
type ArticleDates = { published: string; modified: string; locales?: Record<string, string> };
const table = dates as Record<string, ArticleDates>;

const publishAt = new Map(allArticles.flatMap((item) => (item.publishAt ? [[item.slug, item.publishAt] as const] : [])));

export function articleDates(slug: string): ArticleDates | undefined {
  const dates = table[slug];
  const day = publishAt.get(slug);
  if (!day) return dates;
  if (!dates) return { published: day, modified: day };
  return { ...dates, published: laterDate(dates.published, day)!, modified: laterDate(dates.modified, day)! };
}

/** The day a locale's translation of a guide last changed, if it has ever been committed. */
export function translationDate(slug: string, locale: string): string | undefined {
  const date = table[slug]?.locales?.[locale];
  return date && laterDate(date, publishAt.get(slug));
}

/** "18 August 2026" in English, "18. August 2026" in German: the form the article header shows. */
export function formatArticleDate(iso: string, intl = "en-AU"): string {
  return new Date(`${iso}T00:00:00Z`).toLocaleDateString(intl, { day: "numeric", month: "long", year: "numeric", timeZone: "UTC" });
}
